class Account {
  public static void main(String[] args) {
    double balance = 6000;
    double rateOfInterest = 0.10;
    double interest;
    double withdrawal = 500, deposit = 600;

    for(int i = 1; i <= 12; ++i) {
      balance += deposit;
      balance -= withdrawal;
      interest = balance * rateOfInterest;
      balance += interest;
      System.out.println("The interest for the month " + i + " is " + interest);
    }
    System.out.println("The balance at the end of the year is " + balance);
  }
}

class WithLabelledLoop {
  public static void main(String args[]) {
    int i, j;
    loop1: for(i = 1; i <= 10; i++) {
      System.out.println();
      for(j = 1; j <= 10; j++) {
        System.out.print(j + " ");
        if(j == 5)
          break loop1;
      }
    }
  }
}

